/**
 * Robots.txt for Ellixorrr.
 *
 * Generated by Next.js App Router at /robots.txt.
 *
 * Allows crawling of public website content, declares the sitemap location,
 * and discourages crawling of private application routes (/auth, /dashboard,
 * /admin). robots.txt is not an access-control mechanism; those routes are
 * protected by server-side authorization independent of this file.
 */
import { MetadataRoute } from "next";
import { absoluteRootUrl } from "@/lib/site-config";

export default async function robots(): Promise<MetadataRoute.Robots> {
  const sitemapUrl = absoluteRootUrl("/sitemap.xml");

  return {
    rules: [
      {
        userAgent: "*",
        allow: "/",
        disallow: ["/auth/", "/dashboard/", "/admin/"],
      },
      // AI crawler policy: balanced approach.
      // Allow search-engine-related and research crawlers; disallow
      // AI-training-focused crawlers. robots.txt is advisory only —
      // authorization is enforced server-side independent of this file.
      {
        userAgent: ["GPTBot", "ChatGPT-User", "anthropic-ai"],
        disallow: "/",
      },
      {
        userAgent: ["Google-Extended", "CCBot"],
        allow: "/",
        disallow: ["/auth/", "/dashboard/", "/admin/"],
      },
    ],
    sitemap: sitemapUrl,
  };
}
